insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions, benefit, source) values
  ('steering-obstacle-course-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Steering Obstacle Course', 'A hands-on challenge that builds cycling and steering control.', 13, '10–15 min', 'Trike + plastic bottles, old shoes or steel tumblers as markers', 'Navigate around markers (plastic bottles, old shoes or steel tumblers) at speed. Complex steering + speed control.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('copy-drawing-diamond-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Copy Drawing Diamond', 'A hands-on challenge that builds drawing control and shape copying.', 8, '5–10 min', 'Crayon and paper', 'Diamond shape = two triangles. More complex than triangle; appears 4–5 years. Begin exploring it with guided tracing.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('write-first-name-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Write First Name', 'A play-based activity for strengthening pre-writing and letter formation.', 8, '5–10 min', 'Pencil and paper', 'First attempt at unaided name writing. Any recognisable letters = progress. Letter formation before order: order comes second.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('craft-project-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Craft Project', 'A hands-on challenge that builds construction and spatial precision.', 18, '15–20 min', 'Paper, scissors, glue, tape', 'Build a paper crown, collage, or model from 4+ steps with different materials. Planning and sequencing a multi-material project.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('use-ruler-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Use Ruler', 'An activity that develops fine motor precision.', 8, '5–10 min', 'Ruler', 'Measure objects with a ruler: ''This book is 20 centimetres long.'' Combining numeracy with fine motor tool use.', 'Precision at this age comes from doing things with the hands repeatedly, not from being taught how. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('fold-paper-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Fold Paper', 'A play-based activity for strengthening precision folding.', 13, '10–15 min', 'Paper', 'Fold paper boat or simple origami frog. 4–5 creases requiring precise spatial awareness and planning.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('braid-3-strands-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Braid 3 Strands', 'An activity that develops scissor skills and bilateral control.', 13, '10–15 min', '3 ribbons or cords', 'Demonstrate and let child attempt braiding 3 ribbons or cords. The over-under-over pattern is executive function in the hands.', 'Precision at this age comes from doing things with the hands repeatedly, not from being taught how. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('story-5-events-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Story 5+ Events', 'A play-based activity for strengthening narrative skills and retelling.', 8, '5–10 min', 'None', 'Spontaneous storytelling with a character, a problem, 3 events, and a resolution. Narrative structure growing.', 'This builds the language your child will use to reason, explain and eventually read. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('ask-answer-why-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Ask Answer ''Why''', 'A play-based activity for strengthening reasoning through language.', 8, '5–10 min', 'None', 'Sustain a chain of why-question-and-answer 3 turns deep. Each answer must be a full sentence.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('full-alphabet-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Full Alphabet', 'An activity that develops narrative skills and retelling.', 8, '5–10 min', 'None', 'Introduce the alphabet song. Letter names before letter sounds: the song is a memory sequence, not phonics yet.', 'This builds the language your child will use to reason, explain and eventually read. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('describe-yesterday-detail-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Describe Yesterday Detail', 'An activity that develops narrative skills and retelling.', 8, '5–10 min', 'None', 'Tell me 5 things you did yesterday.'' Episodic memory recall + narrative sequencing in combination.', 'This builds the language your child will use to reason, explain and eventually read. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('compound-sentences-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Compound Sentences', 'A hands-on challenge that builds expressive and receptive language.', null, 'Ongoing', 'None', 'The dog ran AND the cat hid.'' Compound sentences (two clauses joined by ''and'', ''but'', ''so'') are a grammar milestone.', 'This builds the language your child will use to reason, explain and eventually read. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('word-families-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Word Families', 'An activity that develops phonological awareness.', 7, '5–8 min', 'None', '-at words: cat, bat, sat, mat, hat.'' Word families build phonological pattern recognition.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('conversations-adults-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Conversations Adults', 'An activity that develops conversation and turn-taking.', 8, '5–10 min', 'None', '5-turn conversation with an unfamiliar adult. Sustaining conversation with non-family adults = social language milestone.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('read-environmental-print-y3_0', 'communication'::domain, 'y3_0'::age_band, 'Read Environmental Print', 'A play-based activity for strengthening early literacy.', null, 'Ongoing', 'None (outdoors)', 'Read familiar logos, signs, and labels in the environment: shop name, cereal box, road signs. Environmental print = first reading.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('addition-5-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Addition 5', 'A play-based activity for strengthening number sense and early maths.', 7, '5–8 min', 'Fruit or objects', '3 bananas + 2 bananas = 5 bananas.'' Concrete object addition. The concept of adding before the symbol.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('subtraction-5-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Subtraction 5', 'A play-based activity for strengthening number sense and early maths.', 7, '5–8 min', '5 small objects', '5 blocks. Take away 2. How many left?'' Concrete subtraction. Count what remains, not just recite the answer.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('measurement-comparison-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Measurement Comparison', 'A play-based activity for strengthening number sense and early maths.', 7, '5–8 min', 'Two sticks or two cups', 'Which stick is longer? Which cup holds more?'' Direct comparison measurement before formal units.', 'Children this age learn concepts by handling them physically before they can handle them abstractly. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('days-week-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Days Week', 'A hands-on challenge that builds pattern and sequence recognition.', 7, '5–8 min', 'Simple calendar or drawn week', 'Sing and recite days of the week in order. Mark each day on a simple calendar together.', 'Children this age learn concepts by handling them physically before they can handle them abstractly. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('pattern-aabbc-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Pattern AABBC', 'An activity that develops number sense and early maths.', 7, '5–8 min', 'Coloured objects', 'More complex pattern: red, red, blue, blue, green. 5-element pattern before repeating: demands higher working memory.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('map-making-i-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Map Making I', 'A play-based activity for strengthening spatial reasoning and problem-solving.', 13, '10–15 min', 'Paper and crayon', 'Draw a simple map of one room together. Spatial representation (map making) is abstract spatial cognition beginning.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('cooperative-building-project-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Cooperative Building Project', 'A play-based activity for strengthening friendship and cooperative play.', 18, '15–20 min', 'Blankets, cushions, blocks', 'Build something together that neither could build alone: a fort, a long train, a tall tower. True cooperation with shared goal.', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('conflict-resolution-role-play-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Conflict Resolution Role-Play', 'A play-based activity for strengthening conflict resolution.', 8, '5–10 min', 'None', 'Act out a common conflict and try different resolutions. Role-playing the resolution builds the script for real situations.', 'Children this age can begin to name feelings and see another point of view, with support. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('emotion-intensity-scale-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Emotion Intensity Scale', 'A hands-on challenge that builds emotional regulation and vocabulary.', 7, '5–8 min', 'None', 'How big are your feelings? A little bit or a LOT?'' Emotion intensity awareness before intensity regulation.', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('plan-activity-together-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Plan Activity Together', 'A play-based activity for strengthening social skills and emotional understanding.', 8, '5–10 min', 'None', 'What shall we do this afternoon? What do we need? What should we do first?'' Child-led planning with support.', 'Children this age can begin to name feelings and see another point of view, with support. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('appreciate-differences-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Appreciate Differences', 'A play-based activity for strengthening friendship and cooperative play.', null, 'Ongoing', 'None', 'Your friend likes climbing. You like painting. Both are great.'' Differences in preference as valid and interesting: not better/worse.', 'Children this age can begin to name feelings and see another point of view, with support. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('celebrate-others-successes-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Celebrate Others'' Successes', 'A play-based activity for strengthening friendship and cooperative play.', null, 'Ongoing', 'None', 'When a friend achieves something: ''How do you feel about what they did? Can you tell them?'' Pro-social emotion building.', 'Children this age can begin to name feelings and see another point of view, with support. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('clay-sculpture-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Clay Sculpture', 'A play-based activity for strengthening tactile discrimination.', 18, '15–20 min', 'Clay or atta dough', 'Make something from clay without a model or prompt. Imagination into 3D form: high-level creative and fine motor combined.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('sound-mapping-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Sound Mapping', 'A play-based activity for strengthening auditory discrimination.', 13, '10–15 min', 'Paper and crayons', 'Draw a map of sounds heard in the house: kitchen sounds, garden sounds. Audio representation in a visual medium.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('texture-collage-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Texture Collage', 'A play-based activity for strengthening tactile discrimination.', 18, '15–20 min', 'Various texture samples, card, glue', 'Collect 10 different textures (sandpaper, foil, fabric, bark) and stick on card. The making and the touching are both the activity.', 'Hands-on sensory work builds both discrimination and the vocabulary to describe what they notice. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('cooking-mix-pour-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Cooking Mix Pour', 'A play-based activity for strengthening water play and sensory exploration.', 25, '20–30 min', 'Cooking ingredients and tools', 'Involve child in making a simple dish: pancake batter, lemonade. Measuring, pouring, mixing = sensory + numeracy + fine motor.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('mindful-breathing-y3_0', 'cognitive'::domain, 'y3_0'::age_band, 'Mindful Breathing', 'An activity that develops sensory discrimination and integration.', 3, '2–3 min', 'None', 'Let''s take 3 big breaths together. In through the nose, out through the mouth.'' Begin building breath as a self-regulation tool.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('dress-completely-independently-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Dress Completely Independently', 'A play-based activity for strengthening dressing independence.', 13, '10–15 min', 'Clothing', 'Full dress sequence independently except challenging fastenings. Independence in self-care is as developmental as any skill.', 'This develops the independence that starting school will require. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('make-own-breakfast-y3_0', 'social_emotional'::domain, 'y3_0'::age_band, 'Make Own Breakfast', 'A hands-on challenge that builds independent eating and serving.', 13, '10–15 min', 'Simple breakfast items', 'Pour cereal, peel banana, spread butter on toast. Self-feeding preparation builds agency, fine motor, and self-reliance.', 'This develops the independence that starting school will require. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('skip-change-direction-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Skip Change Direction', 'A hands-on challenge that builds jumping, hopping and skipping.', 8, '5–10 min', 'None', 'Skip, then on a signal change direction. Changing a skill mid-execution is a high-level motor planning task.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('kick-moving-ball-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Kick Moving Ball', 'A hands-on challenge that builds kicking and foot control.', 8, '5–10 min', 'Ball', 'Kick a ball rolled toward them: timing a kick to a moving target is significantly harder than kicking a stationary one.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('hop-distance-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Hop Distance', 'An activity that develops jumping, hopping and skipping.', 8, '5–10 min', 'None', 'Hop across a room on one foot: 5+ metres. Distance hopping builds stamina as well as motor control.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('beam-walk-backward-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Beam Walk Backward', 'A hands-on challenge that builds balance and postural control.', 7, '5–8 min', 'Tape line', 'With you standing right beside them ready to steady them, walk backward along a tape line without stepping off. Backward balance beam requires proprioceptive awareness.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('vs-jog-signal-y3_3', 'motor'::domain, 'y3_3'::age_band, 'vs Jog Signal', 'A hands-on challenge that builds running and agility.', 8, '5–10 min', 'Open space', 'Run at full speed to a point when they hear ''go'', slow to a jog on ''slow.'' Speed modulation on command.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('catch-both-hands-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Catch Both Hands', 'An activity that develops throwing, catching and hand-eye coordination.', 8, '5–10 min', 'Tennis ball', 'Catching a tennis-ball-sized object thrown from 2 m with two hands closing at the right moment.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('jump-rope-ii-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Jump Rope II', 'An activity that develops jumping, hopping and skipping.', 13, '10–15 min', 'Short rope', 'Begin learning to turn a short rope independently and jump. Step over first, then small jumps, then rhythmic jumping.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('side-slide-steps-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Side Slide Steps', 'A play-based activity for strengthening coordination and physical confidence.', 7, '5–8 min', 'None', 'Step-slide-step sideways in both directions. Lateral movement uses a different motor pattern from forward locomotion.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('copy-initials-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Copy Initials', 'An activity that develops pre-writing and letter formation.', 8, '5–10 min', 'Pencil and paper', 'Write first and last name initials without tracing. Letter formation from memory, not visual copying.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('mosaic-tile-placement-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Mosaic Tile Placement', 'A hands-on challenge that builds drawing control and shape copying.', 18, '15–20 min', 'Small coloured squares, grid paper, glue', 'Stick small squares of coloured paper onto a grid to make a pattern. Precision placement in a constrained space.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('use-stapler-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Use Stapler', 'A hands-on challenge that builds fine motor precision.', 8, '5–10 min', 'Stapler and paper', 'Supervised stapler use. Knowing the correct pressure and position = tool awareness and fine motor calibration.', 'Precision at this age comes from doing things with the hands repeatedly, not from being taught how. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('zig-zag-cutting-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Zig-Zag Cutting', 'An activity that develops scissor skills and bilateral control.', 8, '5–10 min', 'Child scissors and paper', 'Cut along a zig-zag line. Directional change while cutting is harder than cutting a curve.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('weave-fabric-strips-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Weave Fabric Strips', 'A play-based activity for strengthening threading and precision.', 18, '15–20 min', 'Cloth strips, cardboard with slots', 'Weave cloth strips over and under cardboard loom slots. Over-under alternation sustained across a whole piece.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('pin-and-thread-simple-embroidery-y3_3', 'motor'::domain, 'y3_3'::age_band, 'Pin-and-Thread Simple Embroidery', 'A play-based activity for strengthening threading and precision.', 18, '15–20 min', 'Large-eyed blunt needle, fabric, thread', 'With an adult supervising closely, thread a large-eyed blunt needle and make a running stitch on open-weave fabric. Tactile + fine motor + sequencing.', 'Precision at this age comes from doing things with the hands repeatedly, not from being taught how. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('1500-word-vocabulary-y3_3', 'communication'::domain, 'y3_3'::age_band, '1500+ Word Vocabulary', 'An activity that develops vocabulary and description.', null, 'Ongoing', 'None', 'At 3y6m, vocabulary is typically 1200–1500 words. Sentences are 5–6 words with complex grammar emerging.', 'This builds the language your child will use to reason, explain and eventually read. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-dictated-sentence-y3_3', 'communication'::domain, 'y3_3'::age_band, 'Write Dictated Sentence', 'A hands-on challenge that builds expressive and receptive language.', 8, '5–10 min', 'Pencil and paper', 'Say a sentence; child repeats, then writes it with whatever letters they know. Any attempt that maps to the sentence is progress.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('simple-c-v-c-words-y3_3', 'communication'::domain, 'y3_3'::age_band, 'Simple C-V-C Words', 'A hands-on challenge that builds phonological awareness.', 8, '5–10 min', 'Paper with simple words', 'Cat, sat, mat, big, fit. Sound-blending 3-letter words: c-a-t = cat. The first reading bridge.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('use-conjunctions-y3_3', 'communication'::domain, 'y3_3'::age_band, 'Use Conjunctions', 'A play-based activity for strengthening expressive and receptive language.', null, 'Ongoing', 'None', 'I was cold, SO I put on a jumper.'' Complex clause connectors = significant grammar sophistication.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('explain-process-step-by-step-y3_3', 'communication'::domain, 'y3_3'::age_band, 'Explain Process Step-by-Step', 'A play-based activity for strengthening narrative skills and retelling.', 8, '5–10 min', 'None', 'How do you make a sandwich? Tell me each step.'' Procedural language: sequenced instruction giving.', 'This builds the language your child will use to reason, explain and eventually read. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('conversation-repair-y3_3', 'communication'::domain, 'y3_3'::age_band, 'Conversation Repair', 'A hands-on challenge that builds conversation and turn-taking.', null, 'Ongoing', 'None', 'When communication breaks down, teach: ''I don''t understand: can you say it a different way?'' Repair is advanced pragmatic skill.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('news-sharing-y3_3', 'communication'::domain, 'y3_3'::age_band, 'News Sharing', 'A hands-on challenge that builds expressive and receptive language.', 7, '5–8 min', 'None', 'Daily ''news'' time: ''Tell me one important thing that happened today.'' Selective recall + reporting = executive + language.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('simple-crossword-y3_3', 'communication'::domain, 'y3_3'::age_band, 'Simple Crossword', 'A play-based activity for strengthening vocabulary and description.', 8, '5–10 min', 'Simple picture crossword', 'A 3-clue picture crossword. Name the picture, count letters, fill boxes. Reading + counting + writing combined.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('add-within-10-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Add Within 10', 'An activity that develops number sense and early maths.', 8, '5–10 min', '10 small objects', 'Here are 4 blocks. I give you 3 more. How many altogether?'' Count all strategy: touching each object to count.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('subtract-within-10-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Subtract Within 10', 'An activity that develops number sense and early maths.', 8, '5–10 min', '10 small objects', 'Remove objects from a group and count what remains. Cover the removed objects so child counts only remaining.', 'Children this age learn concepts by handling them physically before they can handle them abstractly. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('days-week-order-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Days Week Order', 'An activity that develops pattern and sequence recognition.', 7, '5–8 min', 'None', 'Recite days of week reliably in order. Begin linking days to events: ''On Monday we have swimming.''', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AAP Water Safety; Indian Swimming Federation basic safety norms; IAP'),
  ('seasons-concept-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Seasons Concept', 'A hands-on challenge that builds reasoning and problem-solving.', 7, '5–8 min', 'None', 'Name 4 seasons and one characteristic of each. ''Winter is cold. Summer is hot.'' Concept before observation.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('sort-graph-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Sort Graph', 'A hands-on challenge that builds number sense and early maths.', 13, '10–15 min', '20 small objects, paper', 'Sort 20 objects into 3 groups. Count each group. Draw a simple bar graph of the results. Data literacy beginning.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('living-non-living-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Living / Non-Living', 'A play-based activity for strengthening classification and categorisation.', 7, '5–8 min', 'Household objects and toy animals', 'Is a dog living? Is a chair living?'' Living/non-living is the first science classification concept.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('verbally-before-escalation-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Verbally Before Escalation', 'An activity that develops emotional regulation and vocabulary.', null, 'Ongoing', 'None', 'I feel like I need a break before I get too frustrated.'' Body-awareness + self-advocacy + language = emotional executive function.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('introduce-compromise-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Introduce Compromise', 'A play-based activity for strengthening social skills and emotional understanding.', 7, '5–8 min', 'None', 'You want X, I want Y. What if we do X for 10 minutes and then Y?'' Compromise as a concept explicitly taught.', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('identity-i-am-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Identity I Am...', 'A hands-on challenge that builds emotional regulation and vocabulary.', 8, '5–10 min', 'None', 'Tell me 5 things about you.'' Not what you do: who you are. Self-concept building is the 3-year social-emotional task.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('friendship-maintenance-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Friendship Maintenance', 'An activity that develops friendship and cooperative play.', null, 'Ongoing', 'None', 'Your friend seems quiet today. What could you do?'' Friendship requires maintenance actions: teach them explicitly.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('handle-disappointment-script-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Handle Disappointment Script', 'A hands-on challenge that builds emotional regulation and vocabulary.', 4, '3–5 min', 'None', 'You''re disappointed. Let''s say what you''re feeling and think of one thing that might help.'' Disappointment skill.', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('gratitude-practice-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Gratitude Practice', 'A play-based activity for strengthening social skills and emotional understanding.', 4, '3–5 min', 'None', 'Name 3 things you''re grateful for at dinner. Gratitude practice correlates with wellbeing and prosocial behaviour.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('cooking-sensory-experience-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Cooking Sensory Experience', 'A play-based activity for strengthening tactile discrimination.', 25, '20–30 min', 'Flour, water, pan', 'Make chapati or simple bread together. Feel dough, smell cooking, hear sizzle, taste result. All 5 senses in one activity.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('ice-melt-science-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Ice Melt Science', 'An activity that develops water play and sensory exploration.', 18, '15–20 min', 'Ice tray, water, small objects', 'Fill ice trays with water + small objects. Freeze. Let child unmelt at room temperature or with warm water. Science + sensory.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('weaving-natural-materials-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Weaving Natural Materials', 'An activity that develops natural sensory environments.', 18, '15–20 min', 'Sticks for frame, natural materials', 'Weave grass, leaves, and twigs through a simple frame. Outdoor sensory + fine motor + creativity.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('mindful-listening-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'Mindful Listening', 'A play-based activity for strengthening sensory discrimination and integration.', 3, '2–3 min', 'Timer', 'Sit quietly for 2 minutes. When timer rings, share 3 things you heard. Auditory attention + metacognition.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('or-torch-play-y3_3', 'cognitive'::domain, 'y3_3'::age_band, 'or Torch Play', 'An activity that develops water play and sensory exploration.', 13, '10–15 min', 'Torch, coloured acetate or water in bag', 'In a darkened room, explore light through coloured acetate or water. Light science + visual sensory exploration.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('independent-morning-routine-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Independent Morning Routine', 'An activity that develops dressing independence.', 25, '20–30 min', 'None', 'Wake, toilet, wash, dress, breakfast: child completes the entire sequence with minimal reminders. Executive function in action.', 'This develops the independence that starting school will require. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('responsible-one-chore-y3_3', 'social_emotional'::domain, 'y3_3'::age_band, 'Responsible One Chore', 'A hands-on challenge that builds independent eating and serving.', 8, '5–10 min', 'Chore-specific materials', 'One daily chore owned completely: watering a plant, setting the table, feeding a pet. Responsibility + competence.', 'This develops the independence that starting school will require. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('over-moving-object-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Over Moving Object', 'A hands-on challenge that builds jumping, hopping and skipping.', 8, '5–10 min', 'Large ball', 'Jump over a rolling ball. Timing a jump to a moving target is a higher motor planning demand than a stationary jump.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('dribble-run-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Dribble Run', 'A play-based activity for strengthening running and agility.', 13, '10–15 min', 'Medium ball', 'Bounce a ball continuously while walking, then while running. Dual-task automatisation: locomotion + ball control.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('one-leg-balance-y3_6', 'motor'::domain, 'y3_6'::age_band, 'One-Leg Balance', 'A hands-on challenge that builds balance and postural control.', 4, '3–5 min', 'None', '8-second one-foot balance, eyes open. Begin introducing eyes-closed versions briefly.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('summersault-independently-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Summersault Independently', 'A play-based activity for strengthening coordination and physical confidence.', 4, '3–5 min', 'Soft mat or rug', 'Forward roll without assistance. Head tuck, push-off, round-back landing. Proprioception and vestibular combined.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('tandem-walk-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Tandem Walk', 'An activity that develops balance and postural control.', 7, '5–8 min', 'Tape line', 'Walk heel-to-toe in a straight line, arms out. Tandem walking tests balance in a constrained path.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('gallop-music-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Gallop Music', 'A play-based activity for strengthening rhythm and coordinated movement.', 8, '5–10 min', 'Music source', 'Gallop to music, matching the tempo. Rhythmic locomotion: motor planning linked to auditory input.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('target-throwing-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Target Throwing', 'A play-based activity for strengthening throwing, catching and hand-eye coordination.', 7, '5–8 min', 'Ball and container', 'Underhand toss into a basket from 1.5 m. Underhand vs overhand uses different arm mechanics -- both need practice.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('jumping-jacks-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Jumping Jacks', 'A play-based activity for strengthening jumping, hopping and skipping.', 4, '3–5 min', 'None', 'Demonstrate jumping jacks and let child try. Coordinating arm and leg movement simultaneously -- hard at this age.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('letter-formation-practice-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Letter Formation Practice', 'A hands-on challenge that builds pre-writing and letter formation.', 8, '5–10 min', 'Pencil and paper', 'Correct formation of letters A, B, C, D, E. Top-to-bottom and left-to-right directional habits built now last a lifetime.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('watercolour-painting-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Watercolour Painting', 'A play-based activity for strengthening fine motor precision.', 13, '10–15 min', 'Watercolours, brush, water, paper', 'Paint with watercolours, rinsing brush between colours. Controlling dilution and brush pressure = fine motor calibration.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('weaving-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Weaving', 'An activity that develops threading and precision.', 18, '15–20 min', 'Cardboard loom, yarn', 'Simple over-under weaving on a cardboard loom. Alternating the direction of each row = pattern thinking in the hands.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('use-hole-punch-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Use Hole Punch', 'An activity that develops precision folding.', 8, '5–10 min', 'Hole punch and paper', 'Punch holes along the edge of paper to make a lacing card. Using a hole punch requires significant grip force.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('cut-spiral-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Cut Spiral', 'A hands-on challenge that builds drawing control and shape copying.', 8, '5–10 min', 'Child scissors and paper', 'Draw a spiral and cut along the line. The continuously changing direction is the most demanding cutting challenge yet.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('thin-clay-snake-y3_6', 'motor'::domain, 'y3_6'::age_band, 'Thin Clay Snake', 'An activity that develops hand strength and modelling.', 8, '5–10 min', 'Clay or atta dough', 'Roll clay into a long thin snake without breaking it. Fine pressure calibration -- too hard = flatten, too soft = break.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('read-simple-sentences-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Read Simple Sentences', 'An activity that develops phonological awareness.', 8, '5–10 min', 'Simple reader or card with sentences', 'Read 3-word sentences: ''The cat sat.'' Sound each letter, blend. First independent reading = a landmark moment.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-simple-words-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Write Simple Words', 'A hands-on challenge that builds vocabulary and description.', 8, '5–10 min', 'Pencil and paper', 'Write simple consonant-vowel-consonant words: cat, sit, big. Encoding = higher skill than decoding. Celebrate any attempt.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('use-adjectives-adverbs-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Use Adjectives Adverbs', 'A hands-on challenge that builds vocabulary and description.', null, 'Ongoing', 'None', 'The small brown dog ran quickly.'' Describe objects and actions with modifiers -- vocabulary sophistication growing.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('tell-joke-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Tell Joke', 'A hands-on challenge that builds vocabulary and description.', 8, '5–10 min', 'None', 'Learn one simple joke and tell it to someone. Jokes require understanding that words can have two meanings -- abstract language.', 'This builds the language your child will use to reason, explain and eventually read. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('listen-summarise-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Listen Summarise', 'A hands-on challenge that builds early literacy.', 8, '5–10 min', 'Short paragraph from any book', 'Read a short paragraph, then ask: ''What was it about? Say it in two sentences.'' Summarising requires comprehension + language.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('10-sight-words-y3_6', 'communication'::domain, 'y3_6'::age_band, '10 Sight Words', 'A hands-on challenge that builds vocabulary and description.', 8, '5–10 min', 'Cards with sight words', 'Common sight words: the, and, is, it, in, on, a, I, to, he. Sight word reading is memory + print awareness.', 'This builds the language your child will use to reason, explain and eventually read. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('give-directions-someone-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Give Directions Someone', 'A play-based activity for strengthening following multi-step instructions.', 8, '5–10 min', 'None', 'Tell me how to get to the kitchen from here.'' Spatial language + perspective-taking + sequential instruction.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('debate-two-sides-y3_6', 'communication'::domain, 'y3_6'::age_band, 'Debate Two Sides', 'A hands-on challenge that builds reasoning through language.', 8, '5–10 min', 'None', 'Some people think dogs are better than cats. Some think cats are better. What''s your view? Why?'' Beginning of argument.', 'This builds the language your child will use to reason, explain and eventually read. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('addition-subtraction-10-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Addition Subtraction 10', 'A hands-on challenge that builds number sense and early maths.', 8, '5–10 min', 'Objects + pencil and paper', 'Concrete then pictorial then symbolic. ''4+3=?'' on paper, with objects to count if needed.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Piagetian developmental framework; Harvard Center on the Developing Child; IAP'),
  ('even-odd-numbers-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Even Odd Numbers', 'A play-based activity for strengthening number sense and early maths.', 7, '5–8 min', 'Small objects', '2, 4, 6 are even -- can be split into two equal groups. 1, 3, 5 cannot. Concrete splitting before the rule.', 'Children this age learn concepts by handling them physically before they can handle them abstractly. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('months-year-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Months Year', 'A hands-on challenge that builds pattern and sequence recognition.', 7, '5–8 min', 'None', 'Recite months in order. Link each to a family event: ''My birthday is in July.'' Sequence then meaning.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP')
